import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./Home.css";

export default function Home() {
  const navigate = useNavigate();
  const [searchTerm, setSearchTerm] = useState("");
  const [filteredProperties, setFilteredProperties] = useState([]);
  const [showSuggestions, setShowSuggestions] = useState(false);

  const properties = [
    {
      id: 1,
      image: "bakhaw bh.jpg",
      title: "Isidro Boarding House",
      location: "Brgy. Bakhaw, Mandurriao, Iloilo"
    },
    {
      id: 2,
      image: "Mags bh.jpg",
      title: "Maggs Boarding House",
      location: "Burgos St. La Paz"
    },
    {
      id: 3,
      image: "mandu bh 1.jpg",
      title: "WIT Area",
      location: "Pueblo Conception, Mandurriao, Iloilo"
    }
  ];

  const handleSearch = () => {
    const filtered = properties.filter(
      (property) =>
        property.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        property.location.toLowerCase().includes(searchTerm.toLowerCase())
    );
    setFilteredProperties(filtered);
    setShowSuggestions(false);
  };

  const handleSelectSuggestion = (suggestion) => {
    setSearchTerm(suggestion);
    setShowSuggestions(false);
    handleSearch();
  };

  const handleInputChange = (e) => {
    const value = e.target.value;
    setSearchTerm(value);
    if (value.trim() === "") {
      setShowSuggestions(false);
      setFilteredProperties([]);
    } else {
      setShowSuggestions(true);
    }
  };

  const handleViewInfo = (propertyId) => {
    navigate(`/property/${propertyId}`);
  };

  const displayedProperties =
    filteredProperties.length > 0 || searchTerm
      ? filteredProperties
      : properties;

  return (
    <div className="home-container">
      {/* Header section */}
      <div className="header-background">
        <h2 className="header-text">
          "Find your next home away from home—fast, easy, and reliable"
        </h2>

        {/* Search box */}
        <div className="search-container">
          <span className="filter-icon">
            <svg width="24" height="24" viewBox="0 0 20 20" fill="currentColor">
              <path d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" />
            </svg>
          </span>

          <div className="search-bar">
            <input
              type="text"
              placeholder="Search for a place..."
              className="search-input"
              value={searchTerm}
              onChange={handleInputChange}
              onFocus={() => setShowSuggestions(true)}
            />
            <button className="search-button" onClick={handleSearch}>
              Search
            </button>

            {/* Suggestions dropdown */}
            {showSuggestions && searchTerm.trim() !== "" && (
              <ul className="suggestions-list">
                {properties
                  .filter(
                    (property) =>
                      property.title
                        .toLowerCase()
                        .includes(searchTerm.toLowerCase()) ||
                      property.location
                        .toLowerCase()
                        .includes(searchTerm.toLowerCase())
                  )
                  .map((property) => (
                    <li
                      key={property.id}
                      onClick={() =>
                        handleSelectSuggestion(
                          `${property.title} - ${property.location}`
                        )
                      }
                    >
                      {property.title} – {property.location}
                    </li>
                  ))}
              </ul>
            )}
          </div>
        </div>
      </div>

      {/* Explore section */}
      <div className="content-section">
        <h3 className="explore-title">Explore</h3>

        <div className="cards-container">
          {displayedProperties.length > 0 ? (
            displayedProperties.map((property) => (
              <div key={property.id} className="card">
                <img
                  src={property.image}
                  alt={property.title}
                  className="card-image"
                />
                <div className="card-info">
                  <h4>{property.title}</h4>
                  <p>{property.location}</p>
                  <button
                    className="view-button"
                    onClick={() => handleViewInfo(property.id)}
                  >
                    View Info
                  </button>
                </div>
              </div>
            ))
          ) : (
            <p className="no-results">No properties found</p>
          )}
        </div>
      </div>

      <footer className="footer">© 2025 RenterGo. All rights reserved.</footer>
    </div>
  );
}
